          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name collect_13 --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name tests_14 --destination test-output",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          },
          "if": "${{ needs.tests_14.result == 'success' }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci inspect",
          "env": {
            "GH_TOKEN": "${{ github.token }}",
            "TEST_OUTCOME": "${{ needs.tests_14.result }}"
          },
          "id": "control"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-inspect_14",
            "path": "out",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    },
    "self_hosted_14": {
      "needs": [
        "inspect_14"
      ],
      "if": "${{ !cancelled() && needs.inspect_14.outputs.mode == 'self_hosted' && needs.inspect_14.outputs.role != '' }}",
      "runs-on": "ubuntu-24.04",
      "environment": "review-runtime",
      "timeout-minutes": 3,
      "permissions": {
        "contents": "read",
        "actions": "read"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name inspect_14 --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci ssh-worker",
          "env": {
            "REVIEW_SSH_KEY": "${{ secrets.REVIEW_SSH_KEY }}",
            "REVIEW_SSH_HOST": "${{ vars.REVIEW_SSH_HOST }}",
            "REVIEW_SSH_USER": "${{ vars.REVIEW_SSH_USER }}",
            "REVIEW_SSH_PORT": "${{ vars.REVIEW_SSH_PORT }}",
            "REVIEW_SSH_KNOWN_HOSTS": "${{ vars.REVIEW_SSH_KNOWN_HOSTS }}"
          },
          "id": "prepare"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-self_hosted_14",
            "path": "model-result.json",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    },
    "api_14": {
      "needs": [
        "inspect_14"
      ],
      "if": "${{ !cancelled() && needs.inspect_14.outputs.mode == 'api' && needs.inspect_14.outputs.role != '' }}",
      "runs-on": "ubuntu-24.04",
      "environment": "review-runtime",
      "timeout-minutes": 3,
      "permissions": {
        "contents": "read",
        "actions": "read"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name inspect_14 --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci prepare-worker",
          "id": "prepare"
        },
        {
          "name": "Call Codex",
          "id": "codex",
          "uses": "openai/codex-action@13e9c17417b29e9a276f73ec6ed7fb574137d3c3",
          "timeout-minutes": "${{ fromJSON(steps.prepare.outputs.timeout_minutes) }}",
          "continue-on-error": true,
          "with": {
            "openai-api-key": "${{ secrets.OPENAI_API_KEY }}",
            "prompt-file": "request/prompt.md",
            "output-file": "raw-result.json",
            "output-schema-file": "/home/runner/review-input/policy/.review/schemas/model-output.schema.json",
            "working-directory": "/home/runner/review-input",
            "codex-home": "/home/runner/review-home",
            "permission-profile": "review",
            "safety-strategy": "drop-sudo",
            "codex-version": "${{ steps.prepare.outputs.codex_version }}",
            "model": "${{ steps.prepare.outputs.model }}",
            "effort": "${{ steps.prepare.outputs.effort }}",
            "codex-args": "[\"--json\", \"--ephemeral\"]"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci normalize-worker",
          "env": {
            "ACTION_OUTCOME": "${{ steps.codex.outcome }}"
          },
          "if": "${{ always() && !cancelled() }}"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-api_14",
            "path": "model-result.json",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    },
    "collect_14": {
      "needs": [
        "inspect_14",
        "self_hosted_14",
        "api_14"
      ],
      "if": "${{ always() && !cancelled() && needs.inspect_14.result == 'success' }}",
      "runs-on": "ubuntu-24.04",
      "timeout-minutes": 10,
      "permissions": {
        "contents": "write",
        "actions": "read",
        "pull-requests": "write"
      },
      "outputs": {
        "role": "${{ steps.control.outputs.role }}",
        "phase": "${{ steps.control.outputs.phase }}",
        "head": "${{ steps.control.outputs.head }}",
        "mode": "${{ steps.control.outputs.mode }}",
        "terminal": "${{ steps.control.outputs.terminal }}"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name inspect_14 --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name self_hosted_14 --destination worker-output",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          },
          "if": "${{ needs.self_hosted_14.result == 'success' }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name api_14 --destination worker-output",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          },
          "if": "${{ needs.api_14.result == 'success' }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci collect",
          "env": {
            "GH_TOKEN": "${{ github.token }}",
            "SELF_HOSTED_OUTCOME": "${{ needs.self_hosted_14.result }}",
            "API_OUTCOME": "${{ needs.api_14.result }}"
          },
          "id": "control"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-collect_14",
            "path": "out",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    },
    "finish": {
      "needs": [
        "entry",
        "tests_0",
        "inspect_0",
        "self_hosted_0",
        "api_0",
        "collect_0",
        "tests_1",
        "inspect_1",
        "self_hosted_1",
        "api_1",
        "collect_1",
        "tests_2",
        "inspect_2",
        "self_hosted_2",
        "api_2",
        "collect_2",
        "tests_3",
        "inspect_3",
        "self_hosted_3",
        "api_3",
        "collect_3",
        "tests_4",
        "inspect_4",
        "self_hosted_4",
        "api_4",
        "collect_4",
        "tests_5",
        "inspect_5",
        "self_hosted_5",
        "api_5",
        "collect_5",
        "tests_6",
        "inspect_6",
        "self_hosted_6",
        "api_6",
        "collect_6",
        "tests_7",
        "inspect_7",
        "self_hosted_7",
        "api_7",
        "collect_7",
        "tests_8",
        "inspect_8",
        "self_hosted_8",
        "api_8",
        "collect_8",
        "tests_9",
        "inspect_9",
        "self_hosted_9",
        "api_9",
        "collect_9",
        "tests_10",
        "inspect_10",
        "self_hosted_10",
        "api_10",
        "collect_10",
        "tests_11",
        "inspect_11",
        "self_hosted_11",
        "api_11",
        "collect_11",
        "tests_12",
        "inspect_12",
        "self_hosted_12",
        "api_12",
        "collect_12",
        "tests_13",
        "inspect_13",
        "self_hosted_13",
        "api_13",
        "collect_13",
        "tests_14",
        "inspect_14",
        "self_hosted_14",
        "api_14",
        "collect_14"
      ],
      "if": "${{ always() && needs.entry.result == 'success' }}",
      "runs-on": "ubuntu-24.04",
      "timeout-minutes": 5,
      "permissions": {
        "contents": "write",
        "actions": "read",
        "pull-requests": "write"
      },
      "environment": "review-publisher",
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "id": "publisher-token",
          "uses": "actions/create-github-app-token@fee1f7d63c2ff003460e3d139729b119787bc349",
          "with": {
            "app-id": "${{ vars.REVIEW_APP_ID }}",
            "private-key": "${{ secrets.REVIEW_APP_PRIVATE_KEY }}",
            "permission-checks": "write",
            "permission-contents": "read",
            "permission-administration": "read"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci finish",
          "env": {
            "GH_TOKEN": "${{ github.token }}",
            "REVIEW_CHECK_TOKEN": "${{ steps.publisher-token.outputs.token }}",
            "JOB_OUTCOMES": "${{ toJSON(needs) }}"
          }
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-record",
            "path": "out",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    }
  }
}

.github/workflows/review-approve.yml.base:
{
  "name": "Approve scoped review decision",
  "on": {
    "workflow_dispatch": {
      "inputs": {
        "binding": {
          "description": "Canonical binding JSON, reviewed by the operator",
          "required": true,
          "type": "string"
        }
      }
    }
  },
  "permissions": {
    "contents": "read"
  },
  "jobs": {
    "binding": {
      "runs-on": "ubuntu-24.04",
      "outputs": {
        "digest": "${{ steps.binding.outputs.digest }}"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci approval",
          "env": {
            "BINDING": "${{ inputs.binding }}"
          },
          "id": "binding"
        }
      ]
    },
    "approve": {
      "needs": [
        "binding"
      ],
      "name": "approve-${{ needs.binding.outputs.digest }}",
      "runs-on": "ubuntu-24.04",
      "environment": "review-approval",
      "steps": [
        {
          "run": "true"
        }
      ]
    }
  }
}

.github/workflows/review-evaluate.yml.base:
{
  "name": "Evaluate one frozen trial",
  "permissions": {},
  "on": {
    "workflow_dispatch": {
      "inputs": {
        "manifest": {
          "required": true,
          "type": "string",
          "description": "Manifest path relative to .review/evals"
        },
        "case_id": {
          "required": true,
          "type": "string",
          "description": "Confirmed case folder name"
        },
        "configuration": {
          "required": true,
          "type": "string",
          "description": "Frozen configuration digest"
        },
        "trial": {
          "required": true,
          "type": "string",
          "description": "Trial index from the expected manifest"
        }
      }
    }
  },
  "jobs": {
    "entry": {
      "runs-on": "ubuntu-24.04",
      "timeout-minutes": 5,
      "permissions": {
        "contents": "read",
        "actions": "read"
      },
      "outputs": {
        "mode": "${{ steps.control.outputs.mode }}"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-entry",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          },
          "id": "control"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-eval-input",
            "path": "out",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          }
        }
      ]
    },
    "self_hosted": {
      "needs": [
        "entry"
      ],
      "if": "${{ needs.entry.outputs.mode == 'self_hosted' }}",
      "runs-on": "ubuntu-24.04",
      "environment": "review-runtime",
      "timeout-minutes": 60,
      "permissions": {
        "contents": "read",
        "actions": "read"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name eval-input --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-self-hosted",
          "env": {
            "REVIEW_SSH_KEY": "${{ secrets.REVIEW_SSH_KEY }}",
            "REVIEW_SSH_HOST": "${{ vars.REVIEW_SSH_HOST }}",
            "REVIEW_SSH_USER": "${{ vars.REVIEW_SSH_USER }}",
            "REVIEW_SSH_PORT": "${{ vars.REVIEW_SSH_PORT }}",
            "REVIEW_SSH_KNOWN_HOSTS": "${{ vars.REVIEW_SSH_KNOWN_HOSTS }}"
          }
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-eval-record-self_hosted",
            "path": "trial-record.json",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          },
          "if": "${{ always() && !cancelled() }}"
        }
      ]
    },
    "api": {
      "needs": [
        "entry"
      ],
      "if": "${{ needs.entry.outputs.mode == 'api' }}",
      "runs-on": "ubuntu-24.04",
      "environment": "review-runtime",
      "timeout-minutes": 60,
      "permissions": {
        "contents": "read",
        "actions": "read"
      },
      "steps": [
        {
          "uses": "actions/checkout@f548e57e544e1ff5a4c46bf1e1b8685f8e4a348a",
          "with": {
            "ref": "${{ github.workflow_sha }}",
            "path": "trusted",
            "persist-credentials": false
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci fetch-artifact --name eval-input --destination input",
          "env": {
            "GH_TOKEN": "${{ github.token }}"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-request",
          "env": {
            "EVAL_ROLE": "bugs"
          },
          "id": "prepare_bugs"
        },
        {
          "name": "Call Codex",
          "id": "codex_bugs",
          "uses": "openai/codex-action@13e9c17417b29e9a276f73ec6ed7fb574137d3c3",
          "timeout-minutes": "${{ fromJSON(steps.prepare_bugs.outputs.timeout_minutes) }}",
          "continue-on-error": true,
          "with": {
            "openai-api-key": "${{ secrets.OPENAI_API_KEY }}",
            "prompt-file": "request/prompt.md",
            "output-file": "raw-bugs.json",
            "output-schema-file": "/home/runner/review-input/policy/.review/schemas/model-output.schema.json",
            "working-directory": "/home/runner/review-input",
            "codex-home": "/home/runner/review-home",
            "permission-profile": "review",
            "safety-strategy": "drop-sudo",
            "codex-version": "${{ steps.prepare_bugs.outputs.codex_version }}",
            "model": "${{ steps.prepare_bugs.outputs.model }}",
            "effort": "${{ steps.prepare_bugs.outputs.effort }}",
            "codex-args": "[\"--json\", \"--ephemeral\"]"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-normalize",
          "env": {
            "EVAL_ROLE": "bugs",
            "ACTION_OUTCOME": "${{ steps.codex_bugs.outcome }}"
          },
          "if": "${{ always() && !cancelled() }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-request",
          "env": {
            "EVAL_ROLE": "security"
          },
          "id": "prepare_security"
        },
        {
          "name": "Call Codex",
          "id": "codex_security",
          "uses": "openai/codex-action@13e9c17417b29e9a276f73ec6ed7fb574137d3c3",
          "timeout-minutes": "${{ fromJSON(steps.prepare_security.outputs.timeout_minutes) }}",
          "continue-on-error": true,
          "with": {
            "openai-api-key": "${{ secrets.OPENAI_API_KEY }}",
            "prompt-file": "request/prompt.md",
            "output-file": "raw-security.json",
            "output-schema-file": "/home/runner/review-input/policy/.review/schemas/model-output.schema.json",
            "working-directory": "/home/runner/review-input",
            "codex-home": "/home/runner/review-home",
            "permission-profile": "review",
            "safety-strategy": "drop-sudo",
            "codex-version": "${{ steps.prepare_security.outputs.codex_version }}",
            "model": "${{ steps.prepare_security.outputs.model }}",
            "effort": "${{ steps.prepare_security.outputs.effort }}",
            "codex-args": "[\"--json\", \"--ephemeral\"]"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-normalize",
          "env": {
            "EVAL_ROLE": "security",
            "ACTION_OUTCOME": "${{ steps.codex_security.outcome }}"
          },
          "if": "${{ always() && !cancelled() }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-request",
          "env": {
            "EVAL_ROLE": "verify"
          },
          "id": "prepare_verify"
        },
        {
          "name": "Call Codex",
          "id": "codex_verify",
          "uses": "openai/codex-action@13e9c17417b29e9a276f73ec6ed7fb574137d3c3",
          "timeout-minutes": "${{ fromJSON(steps.prepare_verify.outputs.timeout_minutes) }}",
          "continue-on-error": true,
          "with": {
            "openai-api-key": "${{ secrets.OPENAI_API_KEY }}",
            "prompt-file": "request/prompt.md",
            "output-file": "raw-verify.json",
            "output-schema-file": "/home/runner/review-input/policy/.review/schemas/model-output.schema.json",
            "working-directory": "/home/runner/review-input",
            "codex-home": "/home/runner/review-home",
            "permission-profile": "review",
            "safety-strategy": "drop-sudo",
            "codex-version": "${{ steps.prepare_verify.outputs.codex_version }}",
            "model": "${{ steps.prepare_verify.outputs.model }}",
            "effort": "${{ steps.prepare_verify.outputs.effort }}",
            "codex-args": "[\"--json\", \"--ephemeral\"]"
          }
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-normalize",
          "env": {
            "EVAL_ROLE": "verify",
            "ACTION_OUTCOME": "${{ steps.codex_verify.outcome }}"
          },
          "if": "${{ always() && !cancelled() }}"
        },
        {
          "run": "python3 trusted/.review/bin/reviewctl.py ci eval-record",
          "if": "${{ always() && !cancelled() }}"
        },
        {
          "uses": "actions/upload-artifact@cf430e030ddbb5b0abf93d22962f4752f3646cd9",
          "with": {
            "name": "${{ github.run_id }}-${{ github.run_attempt }}-eval-record-api",
            "path": "trial-record.json",
            "retention-days": 14,
            "if-no-files-found": "error",
            "include-hidden-files": true
          },
          "if": "${{ always() && !cancelled() }}"
        }
      ]
    }
  }
}
